static bool wait_for_tty_pipe_event(int event_bit, k_timeout_t timeout)
{
	k_timeout_t start_time = k_uptime_get_32();
	while (!atomic_test_bit(&tty_pipe_events, event_bit)) {
		if (k_uptime_get_32() - start_time > k_timeout_get_ms(timeout)) {
			return false; /* Timeout */
		}
		k_msleep(1); /* Yield to allow other threads to run */
	}
	return true; /* Event set */
}
